const raw = $input.first().json.text || '';

const cleaned = raw
  .trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '');

let result;

try {
  result = JSON.parse(cleaned);
} catch (error) {
  throw new Error(`AI returned invalid JSON: ${error.message}`);
}

const allowedResults = [
  'Strong Match',
  'Review Required',
  'Low Match'
];

if (!allowedResults.includes(result.screening_result)) {
  throw new Error(
    `Invalid screening_result: ${result.screening_result}`
  );
}

const score = Number(result.ai_score);

if (!Number.isFinite(score) || score < 0 || score > 100) {
  throw new Error(`Invalid ai_score: ${result.ai_score}`);
}

result.ai_score = score;

return [
  {
    json: result
  }
];
